# -*- coding: utf-8 -*-
# 第 10 批（C3）：放流水標準（113/12/18）第1條～第9條
E = "ENV-08"
Q = [

(E,"第1條",1,"放流水標準-法源",
 "放流水標準係依何法律之何條項規定訂定？",
 ["依水污染防治法第七條第二項規定訂定之","依水污染防治法第十八條第一項規定訂定之","依水污染防治法施行細則第三條規定訂定之","依環境基本法第十二條第二項規定訂定之"],"a",
 "第1條：本標準依水污染防治法第七條第二項規定訂定之。水污法第7條第1項規定事業、污水下水道系統及建築物污水處理設施排放廢（污）水於地面水體者應符合放流水標準；第2項並授權中央主管機關會商相關目的事業主管機關訂定其適用範圍、管制方式、項目、濃度或總量限值等。",
 "Under which statutory provision are the Effluent Standards issued?",
 ["Article 7, paragraph 2 of the Water Pollution Control Act","Article 18, paragraph 1 of the Water Pollution Control Act","Article 3 of the Enforcement Rules of that same Act","Article 12, paragraph 2 of the Basic Environment Act"],
 "Article 1; see Article 7 of the Water Pollution Control Act."),

(E,"第2條",2,"放流水標準-附表適用",
 "晶圓製造及半導體製造業與光電材料及元件製造業之放流水標準，分別適用何附表？",
 ["晶圓製造及半導體製造業適用附表一，光電材料及元件製造業適用附表二","晶圓製造及半導體製造業適用附表二，光電材料及元件製造業適用附表一","晶圓製造及半導體製造業適用附表三，光電材料及元件製造業適用附表四","晶圓製造及半導體製造業適用附表八，光電材料及元件製造業適用附表九"],"a",
 "第2條第1項第1款第1目、第2目：事業中之晶圓製造及半導體製造業適用附表一，光電材料及元件製造業適用附表二。同款其餘各目依序為石油化學業附表三、化工業附表四、金屬基本工業等附表五、發電廠附表六、海水淡化廠附表七、前七款以外之事業適用附表八。",
 "Which annexes apply to wafer and semiconductor manufacturing, and to optoelectronic materials and components?",
 ["Wafer and semiconductor manufacturing uses Annex 1, optoelectronic materials and components uses Annex 2","Wafer and semiconductor manufacturing uses Annex 2, optoelectronic materials and components uses Annex 1","Wafer and semiconductor manufacturing uses Annex 3, optoelectronic materials and components uses Annex 4","Wafer and semiconductor manufacturing uses Annex 8, optoelectronic materials and components uses Annex 9"],
 "Article 2, paragraph 1, subparagraph 1, items 1 and 2."),

(E,"第2條",2,"放流水標準-石化化工",
 "石油化學業與化工業之放流水標準分別適用何附表？",
 ["石油化學業適用附表三，化工業適用附表四","石油化學業適用附表四，化工業適用附表三","石油化學業適用附表十，化工業適用附表十一","石油化學業適用附表一，化工業適用附表二"],"a",
 "第2條第1項第1款第3目、第4目：石油化學業適用附表三，化工業適用附表四。第5條第2款、第3款並分別定義石油化學業高含氮製程與化工業高含氮製程，二者均以作業廢水水量達放流口許可核准排放水量百分之四十以上為要件。",
 "Which annexes apply to the petrochemical industry and to the chemical industry?",
 ["The petrochemical industry uses Annex 3 and the chemical industry uses Annex 4","The petrochemical industry uses Annex 4 and the chemical industry uses Annex 3","The petrochemical industry uses Annex 10 and the chemical industry uses Annex 11","The petrochemical industry uses Annex 1 and the chemical industry uses Annex 2"],
 "Article 2, paragraph 1, subparagraph 1, items 3 and 4."),

(E,"第2條",3,"放流水標準-金屬電鍍",
 "哪些業別合併適用附表五之放流水標準？",
 ["金屬基本工業、金屬表面處理業、電鍍業和印刷電路板製造業","金屬基本工業、水泥製造業、玻璃製造業和造紙業等四種業別","金屬表面處理業、皮革製造業、紡織染整業和食品製造業等","電鍍業、石油化學業、化工業和晶圓製造及半導體製造業等"],"a",
 "第2條第1項第1款第5目：金屬基本工業、金屬表面處理業、電鍍業和印刷電路板製造業適用附表五。此四業別因製程共通性高且廢水中金屬項目性質相近而合併於同一附表管制；未列舉之其他事業則依第8目適用附表八。",
 "Which industries share Annex 5 of the Effluent Standards?",
 ["Basic metal industry, metal surface treatment, electroplating and printed circuit board manufacturing","Basic metal industry, cement manufacturing, glass manufacturing and pulp and paper manufacturing","Metal surface treatment, leather manufacturing, textile dyeing and finishing, and food manufacturing","Electroplating, petrochemicals, chemicals, and wafer and semiconductor manufacturing industries"],
 "Article 2, paragraph 1, subparagraph 1, item 5."),

(E,"第2條",2,"放流水標準-發電海淡",
 "發電廠、海水淡化廠及前七款以外之事業，各適用何附表？",
 ["發電廠適用附表六，海水淡化廠適用附表七，前七款以外之事業適用附表八","發電廠適用附表七，海水淡化廠適用附表六，前七款以外之事業適用附表五","發電廠適用附表八，海水淡化廠適用附表九，前七款以外之事業適用附表十","發電廠適用附表五，海水淡化廠適用附表八，前七款以外之事業適用附表六"],"a",
 "第2條第1項第1款第6目至第8目：發電廠適用附表六，海水淡化廠適用附表七，前七款以外之事業適用附表八（即一般事業之通則性附表）。第2條之1第2項並就海水淡化廠之適用另有補充規定。",
 "Which annexes apply to power plants, desalination plants and enterprises outside the first seven categories?",
 ["Power plants use Annex 6, desalination plants use Annex 7, and other enterprises use Annex 8","Power plants use Annex 7, desalination plants use Annex 6, and other enterprises use Annex 5","Power plants use Annex 8, desalination plants use Annex 9, and other enterprises use Annex 10","Power plants use Annex 5, desalination plants use Annex 8, and other enterprises use Annex 6"],
 "Article 2, paragraph 1, subparagraph 1, items 6 to 8."),

(E,"第2條",3,"放流水標準-下水道附表",
 "科學工業園區專用污水下水道系統與石油化學專業區專用污水下水道系統，各適用何附表？",
 ["科學工業園區專用污水下水道系統適用附表九，石油化學專業區專用污水下水道系統適用附表十","科學工業園區專用污水下水道系統適用附表十，石油化學專業區專用污水下水道系統適用附表九","科學工業園區專用污水下水道系統適用附表一，石油化學專業區專用污水下水道系統適用附表三","科學工業園區專用污水下水道系統適用附表十一，石油化學專業區專用污水下水道系統適用附表十四"],"a",
 "第2條第1項第2款第1目、第2目：污水下水道系統中，科學工業園區專用污水下水道系統適用附表九，石油化學專業區專用污水下水道系統適用附表十。第2條之1第1項並定工業區污水下水道系統之石油化學業和化工業許可核准納管水量達許可核准排放水量百分之五十以上者適用附表十。",
 "Which annexes apply to science park dedicated sewer systems and petrochemical zone dedicated sewer systems?",
 ["Science park dedicated sewer systems use Annex 9, and petrochemical zone dedicated sewer systems use Annex 10","Science park dedicated sewer systems use Annex 10, and petrochemical zone dedicated sewer systems use Annex 9","Science park dedicated sewer systems use Annex 1, and petrochemical zone dedicated sewer systems use Annex 3","Science park dedicated sewer systems use Annex 11, and petrochemical zone dedicated sewer systems use Annex 14"],
 "Article 2, paragraph 1, subparagraph 2, items 1 and 2."),

(E,"第2條",3,"放流水標準-社區公共",
 "其他工業區專用、社區專用、其他指定地區或場所專用及公共污水下水道系統，各適用何附表？",
 ["其他工業區專用適用附表十一，社區專用適用附表十二，其他指定地區或場所專用適用附表十三，公共污水下水道系統適用附表十四","其他工業區專用適用附表十二，社區專用適用附表十一，其他指定地區或場所專用適用附表十四，公共污水下水道系統適用附表十三","其他工業區專用適用附表九，社區專用適用附表十，其他指定地區或場所專用適用附表十一，公共污水下水道系統適用附表十二","其他工業區專用適用附表十三，社區專用適用附表十四，其他指定地區或場所專用適用附表十五，公共污水下水道系統適用附表十六"],"a",
 "第2條第1項第2款第3目至第6目：其他工業區專用污水下水道系統適用附表十一，社區專用污水下水道系統適用附表十二，其他指定地區或場所專用污水下水道系統適用附表十三，公共污水下水道系統適用附表十四。第3款則定建築物污水處理設施適用附表十五。",
 "Which annexes apply to other industrial park, community, other designated area and public sewer systems?",
 ["Other industrial park systems use Annex 11, community systems Annex 12, other designated area systems Annex 13, and public sewer systems Annex 14","Other industrial park systems use Annex 12, community systems Annex 11, other designated area systems Annex 14, and public sewer systems Annex 13","Other industrial park systems use Annex 9, community systems Annex 10, other designated area systems Annex 11, and public sewer systems Annex 12","Other industrial park systems use Annex 13, community systems Annex 14, other designated area systems Annex 15, and public sewer systems Annex 16"],
 "Article 2, paragraph 1, subparagraph 2, items 3 to 6."),

(E,"第2條",2,"放流水標準-建築物設施",
 "建築物污水處理設施之放流水標準適用何附表？",
 ["適用附表十五","適用附表十四","適用附表十二","適用附表十六"],"a",
 "第2條第1項第3款：建築物污水處理設施適用附表十五。水污法第25條並定建築物污水處理設施之所有人、使用人或管理人應自行或委託清除機構清理之；違反放流水標準者依水污法第41條處新臺幣三千元以上三十萬元以下罰鍰。",
 "Which annex applies to building sewage treatment facilities?",
 ["Annex 15 applies","Annex 14 applies","Annex 12 applies","Annex 16 applies"],
 "Article 2, paragraph 1, subparagraph 3."),

(E,"第2條",3,"放流水標準-重金屬附表十六",
 "排放廢（污）水於總量管制區內特定承受水體者，哪些重金屬項目之限值適用附表十六？",
 ["銅、鋅、總鉻、鎳、鎘、六價鉻等六項重金屬之限值適用附表十六","汞、砷、鉛、銀、硒、鋇等六項重金屬之限值適用附表十六","鐵、錳、鋁、鈣、鎂、鈉等六項金屬之限值適用附表十六","銅、鋅、鉛、汞、砷、鎘等六項重金屬之限值適用附表十六"],"a",
 "第2條第2項：事業、污水下水道系統排放廢（污）水於經直轄市、縣（市）主管機關公告應特予保護農地水體之排放總量管制區內之特定承受水體者，其銅、鋅、總鉻、鎳、鎘、六價鉻之限值適用附表十六。但總量管制區內之事業或污水下水道系統，未排放廢（污）水於總量管制區內特定承受水體者，不適用附表十六規定。",
 "Which heavy metal limits follow Annex 16 for discharge into specified receiving waters in a total load control zone?",
 ["The limits for copper, zinc, total chromium, nickel, cadmium and hexavalent chromium follow Annex 16","The limits for mercury, arsenic, lead, silver, selenium and barium follow the values set out in Annex 16","The limits for iron, manganese, aluminium, calcium, magnesium and sodium follow the values in Annex 16","The limits for copper, zinc, lead, mercury, arsenic and cadmium follow the values set out in Annex 16"],
 "Article 2, paragraph 2."),

(E,"第2條",3,"放流水標準-附表十六例外",
 "位於總量管制區內之事業，在何種情形下不適用附表十六之重金屬限值規定？",
 ["未排放廢（污）水於總量管制區內特定承受水體者，不適用附表十六之規定","未設置放流水水質水量自動監測系統者，即不適用附表十六之規定","排放水量每日未達一千立方公尺者，即不適用附表十六之規定","已依規定申報重金屬檢測結果者，即不適用附表十六之規定"],"a",
 "第2條第2項但書：總量管制區內之事業或污水下水道系統，未排放廢（污）水於總量管制區內特定承受水體者，不適用附表十六規定。換言之，適用與否繫於是否排放於「特定承受水體」，而非僅以是否位於總量管制區內為判斷。",
 "When is an enterprise inside a total load control zone exempt from the Annex 16 heavy metal limits?",
 ["Where it does not discharge wastewater into a specified receiving water body inside that total load control zone","Where it has not installed an automatic effluent quality and quantity monitoring system at its outlet","Where its daily discharge volume does not reach one thousand cubic metres of wastewater","Where it has duly reported its heavy metal testing results to the competent authority as required"],
 "Article 2, paragraph 2, proviso."),

(E,"第2條",2,"放流水標準-特別規定優先",
 "特定業別、區域另定有排放標準，或地方主管機關增訂加嚴轄內放流水標準時，應如何適用？",
 ["依其規定，即優先適用該另定之排放標準或地方增訂加嚴之放流水標準","仍一律適用本標準各附表之限值，另定或加嚴之標準僅供參考不生效力","應由事業就本標準與另定標準擇一適用，並於申請許可時載明所選擇者","應以本標準與另定標準之平均值作為管制限值，並報請中央主管機關核定"],"a",
 "第2條第3項：特定業別、區域之事業、污水下水道系統及建築物污水處理設施，另定有排放標準者，或直轄市、縣（市）主管機關依據本法第七條第二項增訂或加嚴轄內之放流水標準者，依其規定。水污法第7條第2項並定地方增訂或加嚴應報請中央主管機關會商相關目的事業主管機關後核定。",
 "How do specially issued or locally tightened standards interact with these Standards?",
 ["Those provisions govern, so the separately issued or locally tightened effluent standards apply in preference","The annex limits here still always apply, and any separate or tightened standard is merely advisory","The enterprise may choose between them and must state its choice when applying for its permit","The average of the two sets of limits governs, subject to approval by the central competent authority"],
 "Article 2, paragraph 3; see Article 7 of the Act."),

(E,"第2條之1",3,"放流水標準-工業區納管比例",
 "工業區污水下水道系統之石油化學業和化工業許可核准納管水量，達許可核准排放水量多少比例時適用附表十？",
 ["達百分之五十以上者適用附表十，未達百分之五十者適用附表十一","達百分之四十以上者適用附表十，未達百分之四十者適用附表十一","達百分之七十五以上者適用附表十，未達百分之七十五者適用附表十一","達百分之三十以上者適用附表十，未達百分之三十者適用附表十一"],"a",
 "第2條之1第1項：工業區污水下水道系統，其石油化學業和化工業許可核准納管水量達許可核准排放水量百分之五十以上者，適用附表十之規定；未達百分之五十者，適用附表十一之規定。此百分之五十門檻應與第5條高含氮製程之百分之四十門檻、第8條之百分之七十五門檻區辨。",
 "At what share of permitted discharge must petrochemical and chemical intake reach for Annex 10 to apply?",
 ["Fifty percent or more brings Annex 10, and below fifty percent brings Annex 11 instead","Forty percent or more brings Annex 10, and below forty percent brings Annex 11 instead","Seventy five percent or more brings Annex 10, and below that brings Annex 11 instead","Thirty percent or more brings Annex 10, and below thirty percent brings Annex 11 instead"],
 "Article 2-1, paragraph 1; compare the 40% and 75% thresholds elsewhere."),

(E,"第2條之1",3,"放流水標準-海淡廠適用",
 "海水淡化廠排放之廢（污）水，適用之放流水標準如何規定？",
 ["以海水為原水，排放鹵水及過濾反洗廢水、薄膜清洗廢水或其他相關作業廢水混合排放者適用附表七；採海洋放流管線排放於海洋者適用海洋放流管線放流水標準","以海水為原水，排放鹵水及過濾反洗廢水、薄膜清洗廢水混合排放者適用附表八；採海洋放流管線排放於海洋者一律免適用任何放流水標準之限值規定","以海水為原水者適用附表六，以地面水或地下水為原水者適用附表七；採海洋放流管線排放於海洋者應適用公共污水下水道系統之附表十四規定","以海水為原水，排放鹵水及各類作業廢水混合排放者適用附表十六；採海洋放流管線排放於海洋者適用其所在直轄市加嚴之放流水標準規定"],"a",
 "第2條之1第2項：海水淡化廠排放之廢（污）水適用之放流水標準依下列規定：一、以海水為原水，排放鹵水及過濾反洗廢水、薄膜清洗廢水或其他與海水淡化有關作業廢水混合排放者，適用附表七；二、產生之廢（污）水採海洋放流管線排放於海洋者，適用海洋放流管線放流水標準。第2條第1項第1款第7目亦定海水淡化廠適用附表七。",
 "Which standards apply to desalination plant wastewater?",
 ["Seawater feed discharging brine mixed with filter backwash, membrane cleaning or other desalination process water uses Annex 7; ocean outfall pipeline discharge uses the ocean outfall pipeline standards","Seawater feed discharging brine mixed with filter backwash and membrane cleaning water uses Annex 8; ocean outfall pipeline discharge is exempt from every effluent limit whatsoever","Seawater feed uses Annex 6 while surface or groundwater feed uses Annex 7; discharge through an ocean outfall pipeline must instead follow the public sewer system limits in Annex 14","Seawater feed discharging brine mixed with any process water uses Annex 16; discharge through an ocean outfall pipeline follows the tightened local effluent standards of the municipality concerned"],
 "Article 2-1, paragraph 2; see also Article 2, paragraph 1."),

(E,"第2條之1",2,"放流水標準-海洋放流管線",
 "海水淡化廠產生之廢（污）水，採海洋放流管線排放於海洋者，應適用何標準？",
 ["應適用海洋放流管線放流水標準","應適用本標準附表七之各項限值","應適用本標準附表十四之各項限值","應適用地下水污染管制標準之限值"],"a",
 "第2條之1第2項第2款：海水淡化廠產生之廢（污）水採海洋放流管線排放於海洋者，適用海洋放流管線放流水標準，而非本標準附表七。水污法第2條第11款並將設置管線排放於海洋列為水污染防治措施之一，第13條第4項授權中央主管機關訂定該管線之設置、變更、停用等應遵行事項。",
 "Which standards apply where desalination wastewater is discharged to sea by ocean outfall pipeline?",
 ["The ocean outfall pipeline effluent standards apply","The limits in Annex 7 of these Standards apply","The limits in Annex 14 of these Standards apply","The groundwater pollution control standards apply"],
 "Article 2-1, paragraph 2, subparagraph 2."),

(E,"第3條",1,"放流水標準-檢討修正",
 "事業及其所屬公會或環境保護相關團體，就本標準得為何種行為？",
 ["得隨時提出具體科學性數據、資料，供檢討修正之參考","得每五年提出一次書面建議，逾期不予受理其建議內容","得請求中央主管機關暫緩適用該業別附表所定之各項限值","得逕行委託檢驗測定機構重新訂定該業別適用之限值標準"],"a",
 "第3條：事業及其所屬公會或環境保護相關團體得隨時提出具體科學性數據、資料，供檢討修正之參考。此係開放利害關係人與公益團體參與標準檢討之管道，與水污法第14條之1第4項（污染物項目經評估有必要者應於放流水標準新增管制項目）相呼應。",
 "What may enterprises, their trade associations and environmental groups do regarding these Standards?",
 ["Submit concrete scientific data and materials at any time as reference for review and revision","Submit written suggestions once every five years, later submissions being refused outright","Ask the central authority to suspend application of the limits in the annex for their industry","Commission a testing organisation to set new limits for their own industry on their own"],
 "Article 3; compare Article 14-1, paragraph 4 of the Act."),

(E,"第4條",2,"放流水標準-檢測方法",
 "本標準所定之化學需氧量限值及真色色度，分別以何種方式檢測？",
 ["化學需氧量以重鉻酸鉀氧化方式檢測之，真色色度以真色色度法檢測之","化學需氧量以高錳酸鉀氧化方式檢測之，真色色度以分光光度計法檢測之","化學需氧量以生物培養五日方式檢測之，真色色度以目視比色法檢測之","化學需氧量以重鉻酸鉀還原方式檢測之，真色色度以濁度計換算法檢測之"],"a",
 "第4條：本標準所定之化學需氧量限值，係以重鉻酸鉀氧化方式檢測之；真色色度，係以真色色度法檢測之。水污法第68條並定本法所定各項檢測之方法及品質管制事項，由中央主管機關指定公告之；第23條則要求檢驗測定應委託中央主管機關核發許可證之檢驗測定機構辦理。",
 "How are chemical oxygen demand and true colour to be tested under these Standards?",
 ["Chemical oxygen demand is tested by potassium dichromate oxidation, and true colour by the true colour method","Chemical oxygen demand is tested by potassium permanganate oxidation, and true colour by spectrophotometry","Chemical oxygen demand is tested by five day biological incubation, and true colour by visual colour comparison","Chemical oxygen demand is tested by potassium dichromate reduction, and true colour by turbidity meter conversion"],
 "Article 4; see also Articles 23 and 68 of the Act."),

(E,"第4條",2,"放流水標準-COD重要性",
 "本標準就化學需氧量之檢測方式特別明定其氧化劑，其法律意義為何？",
 ["限值須以重鉻酸鉀氧化方式所得數值認定，改以其他氧化方式所得結果不得作為判定符合限值之依據","限值僅為建議值，事業得自行選擇任何氧化方式檢測，所得數值均得作為判定是否符合限值之依據","限值須以生化需氧量之檢測數值換算而得，重鉻酸鉀氧化方式僅適用於總毒性有機物之檢測項目","限值得由檢驗測定機構視水樣性質選擇氧化劑，惟應於檢測報告中載明所選用之氧化劑種類及濃度"],"a",
 "第4條：本標準所定之化學需氧量限值，係以重鉻酸鉀氧化方式檢測之。檢測方法之明定使限值有一致之判定基礎；水污法第68條並定各項檢測方法及品質管制事項由中央主管機關指定公告，第23條要求除經核准外應委託許可之檢驗測定機構辦理，以確保數據之可比性與證據力。",
 "What is the legal significance of specifying the oxidant for chemical oxygen demand?",
 ["Compliance is judged on values obtained by potassium dichromate oxidation, and results from other oxidation methods cannot establish compliance","The limits are only advisory, so an enterprise may pick any oxidation method and every resulting value may be used to judge compliance","The limits are derived by converting biochemical oxygen demand values, dichromate oxidation applying only to total toxic organic testing","The testing organisation may pick the oxidant to suit the sample, provided the report states the type and concentration of the oxidant used"],
 "Article 4; read with Articles 23 and 68 of the Act."),

(E,"第5條",3,"放流水標準-總毒性有機物",
 "本標準所稱總毒性有機物，係指多少種化合物之濃度總和？",
 ["指三十種化合物之濃度總和","指二十九種化合物之濃度總和","指十七種化合物之濃度總和","指九種化合物之濃度總和"],"a",
 "第5條第1款：總毒性有機物指1,2-二氯苯、甲苯、乙苯、三氯甲烷、二氯甲烷、四氯乙烯、三氯乙烯、五氯酚、酚、四氯化碳及萘等計三十種化合物之濃度總和。另第5款總有機磷劑為二十九種、第6款總氨基甲酸鹽為九種、第7款除草劑為七種、第4款戴奧辛則為十七項化合物之毒性當量總和。",
 "How many compounds make up the total toxic organics parameter?",
 ["The sum of concentrations of thirty compounds","The sum of concentrations of twenty nine compounds","The sum of concentrations of seventeen compounds","The sum of concentrations of nine listed compounds"],
 "Article 5, subparagraph 1."),

(E,"第5條",3,"放流水標準-高含氮製程",
 "石油化學業高含氮製程之認定，除屬所列含氮製程外尚須符合何要件？",
 ["其作業廢水水量須達放流口許可核准之排放水量百分之四十以上","其作業廢水水量須達放流口許可核准之排放水量百分之五十以上","其作業廢水水量須達放流口許可核准之排放水量百分之七十五以上","其作業廢水之含氮濃度須達放流水標準所定限值之二倍以上者"],"a",
 "第5條第2款：石油化學業高含氮製程指所列含氮製程，且作業廢水水量達放流口許可核准之排放水量百分之四十以上者，包括三氟化氮與電子級液氨製造程序、丙烯腈製造程序、己內醯胺製造程序、硫酸銨化學製造程序、聚醯胺塑膠（尼龍）製造程序等九款。第3款化工業高含氮製程之比例門檻相同，但列舉製程達二十七款。",
 "Besides being a listed nitrogen process, what else defines a petrochemical high nitrogen process?",
 ["Its process wastewater volume must reach forty percent or more of the permitted discharge volume at the outlet","Its process wastewater volume must reach fifty percent or more of the permitted discharge volume at the outlet","Its process wastewater volume must reach seventy five percent or more of the permitted volume at the outlet","Its process wastewater nitrogen concentration must reach at least twice the limit set in the effluent standards"],
 "Article 5, subparagraph 2; same threshold in subparagraph 3."),

(E,"第5條",3,"放流水標準-石化含氮製程",
 "下列何者屬本標準所列石油化學業高含氮製程之製造程序？",
 ["三氟化氮與電子級液氨製造程序、丙烯腈製造程序、己內醯胺製造程序及硫酸銨化學製造程序","氮肥製造程序、磷酸銨鹽肥料製造程序、尿素化學製造程序及三聚氰胺樹脂製造程序等","苯胺製造程序、乙醇胺化學製造程序、染料製造程序（偶氮染料）及煉焦相關程序等","乙二胺四醋酸鹽化學製造程序、氨基甲酸酯製造程序、尿素甲醛樹脂製造程序等"],"a",
 "第5條第2款所列石油化學業高含氮製程共九目：三氟化氮與電子級液氨製造程序、甲基丙烯酸酯類（MMA）化學製造程序、丙烯腈製造程序、丙烯腈－丁二烯共聚合物（AB）、丙烯腈－丁二烯－苯乙烯共聚合物（ABS）、丙烯腈－苯乙烯共聚合物（AS）化學製造程序、己內醯胺製造程序、硫酸銨化學製造程序、聚醯胺塑膠（尼龍）製造程序。其餘選項所列多屬第3款化工業高含氮製程之製造程序。",
 "Which of these is listed as a petrochemical high nitrogen manufacturing process?",
 ["Nitrogen trifluoride and electronic grade liquid ammonia, acrylonitrile, caprolactam, and ammonium sulphate chemical manufacturing processes","Nitrogen fertiliser, ammonium phosphate fertiliser, urea chemical manufacturing and melamine resin manufacturing processes","Aniline manufacturing, ethanolamine chemical manufacturing, azo dye manufacturing and coke making related processes","Ethylenediaminetetraacetate chemical manufacturing, carbamate manufacturing and urea formaldehyde resin manufacturing and the like"],
 "Article 5, subparagraph 2; the others fall under subparagraph 3."),

(E,"第5條",3,"放流水標準-戴奧辛",
 "本標準所稱戴奧辛之檢測及表示方式為何？",
 ["檢測十七項化合物所得濃度，乘以國際毒性當量因子之總和計算之，並以總毒性當量表示","檢測十七項化合物所得濃度之算術平均值計算之，並以各該化合物之最高濃度值表示","檢測三十項化合物所得濃度之總和計算之，並以毫克每公升為單位之質量濃度表示","檢測二十九項化合物所得濃度乘以檢出率計算之，並以每公升水樣之菌落數表示"],"a",
 "第5條第4款：戴奧辛指以檢測2,3,7,8-四氯戴奧辛、2,3,7,8-四氯呋喃及2,3,7,8-氯化之五氯、六氯、七氯與八氯戴奧辛及呋喃等共十七項化合物所得濃度，乘以國際毒性當量因子（I-TEF）之總和計算之，以總毒性當量（TEQ）表示。第6條第4款並定戴奧辛之單位為皮克－國際－總毒性當量／公升（pg I-TEQ/L）。",
 "How is dioxin measured and expressed under these Standards?",
 ["By testing seventeen compounds and summing their concentrations multiplied by international toxicity equivalency factors, given as total toxicity equivalent","By taking the arithmetic mean of the concentrations of the seventeen compounds tested, expressed as the highest single compound concentration found","By summing the concentrations of the thirty compounds tested, expressed as a mass concentration in milligrams per litre of the water sample","By multiplying the concentrations of the twenty nine compounds tested by the detection rate, expressed as colony counts per litre of water sample"],
 "Article 5, subparagraph 4; units in Article 6, subparagraph 4."),

(E,"第5條",3,"放流水標準-農藥類定義",
 "本標準所稱總有機磷劑、總氨基甲酸鹽及除草劑，分別指多少種化合物濃度之總和？",
 ["總有機磷劑二十九種、總氨基甲酸鹽九種、除草劑七種化合物之濃度總和","總有機磷劑三十種、總氨基甲酸鹽十七種、除草劑九種化合物之濃度總和","總有機磷劑九種、總氨基甲酸鹽二十九種、除草劑三十種化合物之濃度總和","總有機磷劑七種、總氨基甲酸鹽二十九種、除草劑十七種化合物之濃度總和"],"a",
 "第5條第5款至第7款：總有機磷劑指達馬松、美文松、大利松、二硫松、馬拉松、陶斯松、巴拉松等計二十九種化合物之濃度總和；總氨基甲酸鹽指滅必蝨、加保扶、納乃得、安丹、歐殺滅、得滅克、加保利、滅賜克等計九種化合物之濃度總和；除草劑指丁基拉草、巴拉刈、二、四－地、拉草、全滅草、嘉磷塞、二刈計七種化合物之濃度總和。",
 "How many compounds make up total organophosphates, total carbamates and herbicides respectively?",
 ["Twenty nine for total organophosphates, nine for total carbamates and seven for herbicides","Thirty for total organophosphates, seventeen for total carbamates and nine for herbicides","Nine for total organophosphates, twenty nine for total carbamates and thirty for herbicides","Seven for total organophosphates, twenty nine for total carbamates and seventeen for herbicides"],
 "Article 5, subparagraphs 5 to 7."),

(E,"第5條",3,"放流水標準-七日平均值",
 "本標準所稱七日平均值之採樣及計算方式為何？",
 ["間隔每四至八小時採樣一次，每日共四個水樣，混合成一個水樣檢測分析，連續七日測值之算術平均","間隔每二至三小時採樣一次，每日共八個水樣，分別檢測分析後取其最高值，連續七日測值之算術平均","每日於固定時間採樣一次共取七個水樣，混合成一個水樣檢測分析，並以該次分析結果作為七日平均值","間隔每四至八小時採樣一次，每日共四個水樣，分別檢測分析後取其最低值，連續七日測值之幾何平均"],"a",
 "第5條第8款：七日平均值指間隔每四至八小時採樣一次，每日共四個水樣，混合成一個水樣檢測分析，連續七日測值之算術平均。此為部分管制項目之判定方式，與第6條所定「除氫離子濃度指數為一範圍外，均為最大限值」之一般原則併同適用。",
 "How is the seven day average sampled and calculated under these Standards?",
 ["Sampling every four to eight hours for four samples a day, composited into one sample for analysis, then the arithmetic mean of seven consecutive daily values","Sampling every two to three hours for eight samples a day, analysed separately and the highest taken, then the arithmetic mean of seven consecutive daily values","Taking one sample at a fixed time each day for seven samples, composited into one sample for analysis, that single result being the seven day average value","Sampling every four to eight hours for four samples a day, analysed separately and the lowest taken, then the geometric mean of seven consecutive daily values"],
 "Article 5, subparagraph 8."),

(E,"第6條",3,"放流水標準-限值性質",
 "本標準各項目限值之性質為何？何項目為例外？",
 ["除氫離子濃度指數為一範圍外，其餘各項目之限值均為最大限值","除真色色度為一範圍外，其餘各項目之限值均為最小限值不得低於","除大腸桿菌群為一範圍外，其餘各項目之限值均為年平均值之上限","除水溫為一範圍外，其餘各項目之限值均為七日平均值之上限規定"],"a",
 "第6條：本標準各項目限值，除氫離子濃度指數為一範圍外，均為最大限值。氫離子濃度指數（pH）因過酸或過鹼均會影響水體，故以上下限之區間管制，其餘項目則僅設最大值。第7條並定除水溫及氫離子濃度指數外，符合條件之未接觸冷卻水不適用本標準。",
 "What is the nature of the limits, and which item is the exception?",
 ["Except the hydrogen ion concentration index, which is a range, all limits are maximum limits","Except true colour, which is a range, all other limits are minimum values not to be fallen below","Except total coliform, which is a range, all other limits are ceilings on the annual average value","Except water temperature, which is a range, all other limits are ceilings on the seven day average"],
 "Article 6; see also Article 7."),

(E,"第6條",3,"放流水標準-單位",
 "本標準各項目之單位規定為何？",
 ["氫離子濃度指數及真色色度無單位，大腸桿菌群為CFU/100 mL，戴奧辛為pg I-TEQ/L，其餘各項目為毫克／公升","氫離子濃度指數及真色色度為毫克／公升，大腸桿菌群為CFU/L，戴奧辛為毫克／公升，其餘各項目均為微克／公升","氫離子濃度指數及大腸桿菌群無單位，真色色度為CFU/100 mL，戴奧辛為ng I-TEQ/L，其餘各項目為公克／公升","氫離子濃度指數及戴奧辛無單位，真色色度為pg I-TEQ/L，大腸桿菌群為毫克／公升，其餘各項目為毫克／公斤"],"a",
 "第6條各款：一、氫離子濃度指數：無單位；二、真色色度：無單位；三、大腸桿菌群：每一百毫升水樣在濾膜上所產生之菌落數（CFU/100 mL）；四、戴奧辛：皮克－國際－總毒性當量／公升（pg I-TEQ/L）；五、其餘各項目：毫克／公升。第4條並定化學需氧量以重鉻酸鉀氧化方式檢測、真色色度以真色色度法檢測。",
 "What units apply to the parameters under these Standards?",
 ["pH and true colour are unitless, total coliform is CFU/100 mL, dioxin is pg I-TEQ/L, and all remaining items are milligrams per litre","pH and true colour are milligrams per litre, total coliform is CFU/L, dioxin is milligrams per litre, and all remaining items are micrograms per litre","pH and total coliform are unitless, true colour is CFU/100 mL, dioxin is ng I-TEQ/L, and all remaining items are expressed in grams per litre","pH and dioxin are unitless, true colour is pg I-TEQ/L, total coliform is milligrams per litre, and all remaining items are milligrams per kilogram"],
 "Article 6, subparagraphs 1 to 5."),

(E,"第6條",2,"放流水標準-大腸桿菌群",
 "本標準所定大腸桿菌群之單位如何表示？",
 ["每一百毫升水樣在濾膜上所產生之菌落數，即CFU/100 mL","每一公升水樣在培養皿中所產生之菌落數，即CFU/L","每一百毫升水樣之毒性當量，即pg I-TEQ/100 mL","每一公升水樣中之菌體質量濃度，即毫克／公升"],"a",
 "第6條第3款：大腸桿菌群之單位為每一百毫升水樣在濾膜上所產生之菌落數（CFU/100 mL）。同條第4款定戴奧辛單位為pg I-TEQ/L，第1款、第2款定氫離子濃度指數與真色色度無單位，第5款定其餘項目為毫克／公升。",
 "How is the unit for total coliform expressed under these Standards?",
 ["Colony forming units on the filter membrane per one hundred millilitre sample, CFU/100 mL","Colony forming units in the culture dish per one litre of water sample, expressed as CFU/L","Toxicity equivalent per one hundred millilitres of sample, expressed as pg I-TEQ/100 mL","Mass concentration of bacterial cells per litre of sample, expressed in milligrams per litre"],
 "Article 6, subparagraph 3."),

(E,"第6條",2,"放流水標準-無單位項目",
 "本標準所定哪些項目係無單位之管制項目？",
 ["氫離子濃度指數及真色色度二項目無單位","大腸桿菌群及戴奧辛二項目均無單位規定","化學需氧量及懸浮固體二項目均無單位","水溫及總毒性有機物二項目均無單位規定"],"a",
 "第6條第1款、第2款：氫離子濃度指數無單位；真色色度亦無單位。第4條並定真色色度係以真色色度法檢測之；第6條本文則定除氫離子濃度指數為一範圍外，各項目限值均為最大限值，故真色色度雖無單位，仍屬最大限值之管制項目。",
 "Which parameters are expressed without any unit under these Standards?",
 ["The hydrogen ion concentration index and true colour are both unitless","Total coliform and dioxin are the two parameters without any unit","Chemical oxygen demand and suspended solids are both unitless items","Water temperature and total toxic organics are both unitless items"],
 "Article 6, subparagraphs 1 and 2."),

(E,"第7條",3,"放流水標準-未接觸冷卻水",
 "事業自水體取水作為冷卻或循環用途之未接觸冷卻水，在何條件下不適用本標準？哪些項目仍應適用？",
 ["如排放於原取水區位之地面水體者不適用本標準；但水溫及氫離子濃度指數二項目之限值仍應適用","如排放於任何地面水體者均不適用本標準；但化學需氧量及懸浮固體二項目之限值仍應適用","如經主管機關核准並設置獨立放流口者不適用本標準；但大腸桿菌群及真色色度之限值仍應適用","如冷卻水量未達總排放量百分之五十者不適用本標準；但重金屬及總毒性有機物之限值仍應適用"],"a",
 "第7條：本標準各項目限值，除水溫及氫離子濃度指數外，事業或污水下水道系統自水體取水作為冷卻或循環用途之未接觸冷卻水，如排放於原取水區位之地面水體，不適用本標準。故未接觸冷卻水縱符合免適用要件，其水溫與氫離子濃度指數二項目仍受本標準拘束。",
 "When is non contact cooling water exempt from these Standards, and which items still apply?",
 ["Where it is discharged back to the surface water at the original intake location; the limits for water temperature and pH still apply to it","Where it is discharged to any surface water body at all; the limits for chemical oxygen demand and suspended solids still apply to it","Where the authority approves and a separate outlet is installed; the limits for total coliform and true colour still apply to it","Where the cooling water is under fifty percent of total discharge; the limits for heavy metals and total toxic organics still apply"],
 "Article 7."),

(E,"第7條",2,"放流水標準-取水區位",
 "未接觸冷卻水欲適用第7條之免適用規定，其排放地點有何限制？",
 ["應排放於原取水區位之地面水體，排放於其他區位或其他水體者仍應適用本標準","得排放於同一縣市內任一地面水體，僅須於申報時載明取水及排放之位置","應排放於下游三公里範圍內之地面水體，並經地方主管機關核准始得為之","得排放於任何地面水體或土壤，惟應設置獨立之放流口並裝設流量計測設施"],"a",
 "第7條：未接觸冷卻水須「如排放於原取水區位之地面水體」始不適用本標準；若排放於其他區位或不同水體，則無本條免適用規定之適用，仍應符合各該附表限值。且縱使符合本條要件，水溫及氫離子濃度指數二項目仍應適用。",
 "What locational limit applies to the Article 7 exemption for non contact cooling water?",
 ["It must be discharged to the surface water at the original intake location; discharge elsewhere remains subject to these Standards","It may go to any surface water body within the same county, the intake and discharge points merely being stated when reporting","It must be discharged to surface water within three kilometres downstream, and only with the approval of the local authority","It may go to any surface water body or to soil, provided a separate outlet with flow measuring equipment is installed"],
 "Article 7."),

(E,"第8條",3,"放流水標準-混合處理",
 "有二種以上不同業別或同一業別有不同製程而廢水混合處理排放者，應如何適用放流水標準？",
 ["應符合各該業別之放流水標準；相同之管制項目有不同管制限值者，應符合較嚴之限值標準","應符合主要業別之放流水標準即可；相同之管制項目有不同管制限值者，應符合較寬之限值","應符合附表八所定一般事業之放流水標準；相同之管制項目有不同限值者取其算術平均值","應由事業自行選擇其中一種業別之放流水標準適用；相同管制項目則依所選業別之限值管制"],"a",
 "第8條第1項前段：事業、污水下水道系統及建築物污水處理設施，同時依本標準適用範圍，有二種以上不同業別或同一業別有不同製程，其廢水混合處理及排放者，應符合各該業別之放流水標準；相同之管制項目有不同管制限值者，應符合較嚴之限值標準。從嚴適用為原則，例外則為同項後段之百分之七十五規定。",
 "How do the standards apply where wastewater from two or more industries or processes is treated and discharged together?",
 ["It must meet the standards of each industry concerned, and where a shared item has differing limits the stricter limit governs","It need only meet the standards of the principal industry, and where a shared item has differing limits the looser limit governs","It must meet the general enterprise standards in Annex 8, and where a shared item has differing limits their arithmetic mean governs","The enterprise may choose one industry's standards to follow, and shared items are then controlled by that industry's limits"],
 "Article 8, paragraph 1, first part."),

(E,"第8條",3,"放流水標準-七十五比例",
 "廢水混合處理排放者，在何條件下得申請以單一業別之放流水標準管制共同管制項目？",
 ["各業別中之一種業別廢水水量達總廢水量百分之七十五以上，並裝設有獨立專用累計型水量計測設施者，得向主管機關申請","各業別中之一種業別廢水水量達總廢水量百分之五十以上，並經環境工程技師簽證確認水量比例者，得向主管機關申請","各業別中之一種業別廢水水量達總廢水量百分之四十以上，並設置放流水水質水量自動監測系統者，得向主管機關申請","各業別中之一種業別產值達總產值百分之七十五以上，並取得該業別公會出具之證明文件者，得向主管機關申請"],"a",
 "第8條第1項後段：各業別中之一種業別廢水水量達總廢水量百分之七十五以上，並裝設有獨立專用累計型水量計測設施者，得向主管機關申請對共同管制項目以該業別放流水標準管制。此百分之七十五門檻應與第2條之1第1項之百分之五十、第5條高含氮製程之百分之四十區辨。",
 "On what conditions may one industry's standards govern the shared items of mixed wastewater?",
 ["Where one industry's wastewater reaches seventy five percent or more of total wastewater and a dedicated cumulative flow meter is installed, on application to the authority","Where one industry's wastewater reaches fifty percent or more of total wastewater and an environmental engineer certifies the proportion, on application to the authority","Where one industry's wastewater reaches forty percent or more of total wastewater and an automatic effluent monitoring system is installed, on application to the authority","Where one industry's output value reaches seventy five percent or more of total output and its trade association issues a certificate, on application to the authority"],
 "Article 8, paragraph 1, latter part."),

(E,"第8條",2,"放流水標準-比例計算",
 "依第8條申請以單一業別標準管制者，其廢水量所佔比例應如何計算？",
 ["以申請日前半年之紀錄計算之","以申請日前一整年之紀錄計算之","以申請日前一個月之紀錄計算之","以申請日當日之實測水量計算之"],"a",
 "第8條第2項：前項廢水量所佔比例，以申請日前半年之紀錄計算之。故事業須有連續半年之獨立專用累計型水量計測紀錄，始能證明該業別廢水水量達總廢水量百分之七十五以上而據以申請。",
 "Over what period is the wastewater proportion calculated for an Article 8 application?",
 ["It is calculated from the records of the six months before the application date","It is calculated from the records of the full year before the application date","It is calculated from the records of the one month before the application date","It is calculated from the flow actually measured on the application date itself"],
 "Article 8, paragraph 2."),

(E,"第8條",3,"放流水標準-從嚴原則",
 "廢水混合處理排放而相同管制項目有不同限值時，其適用原則為何？",
 ["應符合較嚴之限值標準，以確保各業別之管制目的均能達成","應符合較寬之限值標準，以兼顧事業處理成本與可行性之考量","應符合先取得許可之業別限值，後續納入之業別限值不予適用","應由主管機關就個案指定應適用之限值，事業不得自行主張適用"],"a",
 "第8條第1項：相同之管制項目有不同管制限值者，應符合較嚴之限值標準。此從嚴原則之例外，為同項後段所定一種業別廢水水量達總廢水量百分之七十五以上並裝設獨立專用累計型水量計測設施者，得申請對共同管制項目以該業別放流水標準管制。",
 "Where a shared control item carries different limits, which principle governs?",
 ["The stricter limit must be met, so that the control purpose of each industry is achieved","The looser limit must be met, in view of treatment costs and practical feasibility","The limit of the industry permitted first governs, later added industries being disregarded","The authority designates the applicable limit case by case, the enterprise having no say"],
 "Article 8, paragraph 1; exception in the same paragraph."),

(E,"第9條",1,"放流水標準-施行日",
 "本標準之施行日期規定為何？",
 ["除另定施行日期者外，自發布日施行","一律自發布日起六個月後開始施行","一律自發布之次年一月一日開始施行","由中央主管機關另以公告指定施行日"],"a",
 "第9條：本標準除另定施行日期者外，自發布日施行。本標準最近一次修正日期為民國113年12月18日。相較之下，水污染防治法第75條規定本法自公布日施行，並無另定施行日期之保留。",
 "When do these Standards take effect?",
 ["From the date of promulgation, unless another effective date is prescribed","Uniformly six months after the date on which they were promulgated","Uniformly from the first day of January in the year after promulgation","On a date separately designated by announcement of the central authority"],
 "Article 9; compare Article 75 of the Act."),

(E,"第2條",2,"放流水標準-適用主體",
 "本標準所規範水質項目及限值之適用主體，包括哪三大類？",
 ["事業、污水下水道系統及建築物污水處理設施三大類","事業、農田水利設施及一般家戶污水排放三大類","工廠、礦場及自來水淨水場等三類供水處理設施","公共下水道、灌溉渠道及海洋放流管線等三大類"],"a",
 "第2條第1項：事業、污水下水道系統及建築物污水處理設施之放流水標準，其水質項目及限值分別依第1款至第3款規定適用各該附表。此與水污法第7條第1項所定應符合放流水標準之三類主體一致。",
 "Which three categories are subject to the water quality items and limits in these Standards?",
 ["Enterprises, sewer systems and building sewage treatment facilities","Enterprises, irrigation facilities and ordinary household sewage discharge","Factories, mines and tap water purification plants as water treatment works","Public sewers, irrigation canals and ocean outfall pipelines as three classes"],
 "Article 2, paragraph 1; see Article 7 of the Act."),

(E,"第2條之1",3,"放流水標準-未達比例",
 "工業區污水下水道系統之石油化學業和化工業許可核准納管水量未達門檻比例者，應適用何附表？",
 ["應適用附表十一之規定，即其他工業區專用污水下水道系統之放流水標準","應適用附表十之規定，即石油化學專業區專用污水下水道系統之放流水標準","應適用附表十四之規定，即公共污水下水道系統所適用之放流水標準限值","應適用附表八之規定，即前七款以外之一般事業所適用之放流水標準限值"],"a",
 "第2條之1第1項後段：工業區污水下水道系統，其石油化學業和化工業許可核准納管水量未達許可核准排放水量百分之五十者，適用附表十一之規定。附表十一即第2條第1項第2款第3目所定其他工業區專用污水下水道系統之放流水標準。",
 "Which annex applies where petrochemical and chemical intake falls below the threshold share?",
 ["Annex 11, being the standards for other industrial park dedicated sewer systems","Annex 10, being the standards for petrochemical zone dedicated sewer systems","Annex 14, being the effluent standards applicable to public sewer systems","Annex 8, being the effluent standards for enterprises outside the seven categories"],
 "Article 2-1, paragraph 1, latter part."),

(E,"第5條",3,"放流水標準-化工含氮製程",
 "化工業高含氮製程之列舉範圍與石油化學業高含氮製程相比有何差異？",
 ["化工業列舉二十七款製程，多於石油化學業之九款，但二者之作業廢水水量比例門檻相同","化工業列舉九款製程，少於石油化學業之二十七款，且其水量比例門檻較石油化學業為低","化工業列舉二十七款製程，多於石油化學業之九款，且其水量比例門檻高於石油化學業者","化工業與石油化學業列舉之製程款數相同，惟化工業之作業廢水水量比例門檻較為嚴格"],"a",
 "第5條第2款列舉石油化學業高含氮製程共九目，第3款列舉化工業高含氮製程共二十七目（含氨化學製造程序、氮肥、銨肥、尿素化學製造程序、苯胺、染料製造程序、煉焦相關程序等）；二者均以作業廢水水量達放流口許可核准之排放水量百分之四十以上為要件。",
 "How does the chemical industry high nitrogen process list differ from the petrochemical one?",
 ["The chemical list has twenty seven processes against nine for petrochemicals, while the wastewater volume threshold is the same","The chemical list has nine processes against twenty seven for petrochemicals, and its volume threshold is lower than the other","The chemical list has twenty seven processes against nine for petrochemicals, and its volume threshold is higher than the other","Both lists contain the same number of processes, but the chemical industry volume threshold is the stricter of the two"],
 "Article 5, subparagraphs 2 and 3."),

(E,"第5條",2,"放流水標準-總氨基甲酸鹽",
 "本標準所稱總氨基甲酸鹽，係指哪些化合物之濃度總和？",
 ["滅必蝨、加保扶、納乃得、安丹、丁基滅必蝨、歐殺滅、得滅克、加保利、滅賜克計九種化合物","丁基拉草、巴拉刈、二、四－地、拉草、全滅草、嘉磷塞、二刈等計七種化合物之濃度總和","達馬松、美文松、滅賜松、普伏松、亞素靈、福瑞松、大滅松等計二十九種化合物之濃度總和","甲苯、乙苯、三氯甲烷、二氯甲烷、四氯乙烯、三氯乙烯、五氯酚等計三十種化合物之總和"],"a",
 "第5條第6款：總氨基甲酸鹽指滅必蝨、加保扶、納乃得、安丹、丁基滅必蝨、歐殺滅、得滅克、加保利、滅賜克計九種化合物之濃度總和。第7款除草劑為七種、第5款總有機磷劑為二十九種、第1款總毒性有機物則為三十種化合物之濃度總和。",
 "Which compounds make up the total carbamates parameter?",
 ["Isoprocarb, carbofuran, methomyl, propoxur, fenobucarb, oxamyl, aldicarb, carbaryl and methiocarb, nine compounds in all","Butachlor, paraquat, 2,4-D, alachlor, molinate, glyphosate and bentazone, seven compounds in all summed together","Methamidophos, mevinphos, fensulfothion, propaphos, monocrotophos and others, twenty nine compounds in all","Toluene, ethylbenzene, chloroform, dichloromethane, tetrachloroethylene, trichloroethylene and others, thirty in all"],
 "Article 5, subparagraph 6."),

(E,"第5條",2,"放流水標準-除草劑",
 "本標準所稱除草劑，係指多少種化合物之濃度總和？包括哪些？",
 ["指丁基拉草、巴拉刈、二、四－地、拉草、全滅草、嘉磷塞、二刈計七種化合物之濃度總和","指丁基拉草、巴拉刈、拉草、全滅草、嘉磷塞計五種化合物之濃度總和並取其算術平均值","指滅必蝨、加保扶、納乃得、安丹、歐殺滅、得滅克、加保利計七種化合物之濃度總和","指達馬松、美文松、滅賜松、大利松、二硫松、馬拉松計六種化合物之濃度總和之半數"],"a",
 "第5條第7款：除草劑指丁基拉草、巴拉刈、二、四－地、拉草、全滅草、嘉磷塞、二刈計七種化合物之濃度總和。此為本標準四類農藥相關定義中種類數最少者，第6款總氨基甲酸鹽為九種，第5款總有機磷劑為二十九種。",
 "How many compounds make up the herbicide parameter, and which ones?",
 ["Seven compounds summed: butachlor, paraquat, 2,4-D, alachlor, molinate, glyphosate and bentazone","Five compounds averaged: butachlor, paraquat, alachlor, molinate and glyphosate, taken as their mean","Seven compounds summed: isoprocarb, carbofuran, methomyl, propoxur, oxamyl, aldicarb and carbaryl","Six compounds halved: methamidophos, mevinphos, fensulfothion, diazinon, disulfoton and malathion"],
 "Article 5, subparagraph 7."),

(E,"第6條",2,"放流水標準-戴奧辛單位",
 "本標準所定戴奧辛之單位為何？",
 ["皮克－國際－總毒性當量／公升，即pg I-TEQ/L","毫克－國際－總毒性當量／公升，即mg I-TEQ/L","每一百毫升水樣所產生之菌落數，即CFU/100 mL","毫克／公升，與其餘各項目之單位規定相同"],"a",
 "第6條第4款：戴奧辛之單位為皮克－國際－總毒性當量／公升（pg I-TEQ/L）。第5條第4款並定戴奧辛係以十七項化合物濃度乘以國際毒性當量因子之總和計算，以總毒性當量表示；第6條第5款則定其餘各項目單位為毫克／公升。",
 "What unit applies to dioxin under these Standards?",
 ["Picogram international toxicity equivalent per litre, pg I-TEQ/L","Milligram international toxicity equivalent per litre, mg I-TEQ/L","Colony forming units per one hundred millilitres, CFU/100 mL","Milligrams per litre, the same unit as all the remaining items"],
 "Article 6, subparagraph 4; see Article 5, subparagraph 4."),
]
